"""Deterministic valid/invalid combinations against independent Java predictions.

Keep generated expectations reproducible, including SLL, LL and exact mode.
Failure cases compare complete recovered trees, not only acceptance.
"""
import argparse,base64,hashlib,json,os,random,subprocess,tempfile
from pathlib import Path
from generate import ANTLR_SHA256,read_interp
ROOT=Path(__file__).resolve().parents[1]
q=lambda value:json.dumps(value,ensure_ascii=False)

def traversal_checks(alias,prefix,row):
    return [
        '  let events : Array[String] = []',
        f'  let listener = {{ ..@{alias}.{prefix}Listener::new(), enter: node => events.push("enter:" + node.name), exit: node => events.push("exit:" + node.name), terminal: token => events.push("token:" + token.text), error: token => events.push("error:" + token.text) }}',
        '  listener.walk(parsed.context)',
        f'  @debug.assert_eq(events, {q(row["events"])})',
        f'  let visitor = @{alias}.{prefix}Visitor::new(terminal=token => if token.kind == -1 {{ "<EOF>" }} else {{ token.text.escape() }}, error=token => "(error " + token.text.escape() + ")", rule=(node, children) => "(" + node.name + (if children.is_empty() {{ "" }} else {{ " " + children.join(" ") }}) + ")")',
        f'  assert_eq(visitor.visit(parsed.context), {q(row["tree"])})',
    ]

def corpus():
    rng=random.Random(20261123)
    expressions=['foo','12','-12','--foo','foo+2*3','(foo+2)*3','2^3^4','-2^3','2^-3','(1+2','1+','1 2','()','',')1','1**2','foo\n+\t2']
    def expression(depth):
        if depth==0:return rng.choice(['foo','bar','12','3'])
        return rng.choice(['('+expression(depth-1)+')','-'+expression(depth-1),expression(depth-1)+rng.choice(['+','-','*','/','^'])+expression(depth-1)])
    expressions += [expression(2) for _ in range(32)]
    small=['','a','a b','a c','a x b','a x y c','a x x b','a y y','a b b','c b b','c b b b','a b c','a x','a x x','a y c b','x','y','foo','foo foo','a foo b','a\n x\t b']
    small += [' '.join(rng.choices(['a','b','c','x','y'],k=rng.randrange(1,7))) for _ in range(36)]
    return {'document':(0,expressions),'choice':(2,small),'nullable':(4,small),'following':(6,small),'ambiguous':(8,small),'reluctant':(11,small),'contexts':(12,small)}

def generate(jar,java,javac,directory):
    subprocess.run([java,'-jar',str(jar),'-encoding','UTF-8','-Xexact-output-dir','-o',str(directory)]+[str(ROOT/'grammars'/name) for name in ['Differential.g4','UnicodeModesLexer.g4','SemanticDifferential.g4','Typed.g4']],check=True)
    subprocess.run([javac,'-encoding','UTF-8','-cp',str(jar),'-d',str(directory)]+list(map(str,directory.glob('*.java')))+[str(ROOT/'tools'/name) for name in ['Oracle.java','UpstreamAttributes.java','PredictionTrace.java','UpstreamLexerOracle.java']],check=True)
    rules=read_interp(directory/'Differential.interp')[1]
    out=['// Generated by tools/differential_oracle.py; seed 20261123; ANTLR 4.13.2 Java.','']
    count=0
    for rule,(_,sources) in corpus().items():
        start=rules.index(rule)
        sources=list(dict.fromkeys(sources))
        payload=''.join(base64.b64encode(source.encode()).decode()+'\n' for source in sources)
        for mode in ['SLL','LL','LL_EXACT_AMBIG_DETECTION']:
            result=subprocess.run([java,'-Dfile.encoding=UTF-8','-Dmoonantlr.predictionMode='+mode,'-cp',str(directory)+os.pathsep+str(jar),'Oracle','Differential',rule,'default'],input=payload,encoding='utf8',capture_output=True,check=True)
            rows=[json.loads(line) for line in result.stdout.splitlines()]
            if len(rows)!=len(sources):raise ValueError('Reference case count differs')
            for index,(source,row) in enumerate(zip(sources,rows)):
                count+=1
                out+=['///|',f'test "differential {rule} {mode} {index:03d}" {{',f'  let parsed = @differential.grammar().parse_default({q(source)}, start_rule={start}, prediction_mode=@runtime.{mode})',f'  assert_eq(parsed.tree.to_sexpr(), {q(row["tree"])})',f'  assert_eq(parsed.context.get_text(), {q(row["contextText"])})',f'  @debug.assert_eq(parsed.diagnostics.map(d => (d.line.unwrap(), d.column.unwrap())), [{", ".join("("+str(line)+", "+str(col)+")" for line,col in row["parserErrors"])}])',f'  assert_eq(parsed.next_token.kind, {row["nextKind"]})',f'  assert_eq(parsed.next_token.text, {q(row["nextText"])})',f'  let expected : Json = @reference_json.parse({q(json.dumps(row["predictionEvents"],ensure_ascii=False,separators=(",",":")))})','  @debug.assert_eq(Json::array(parsed.prediction_events.map(event => event.to_json())), expected)','}','']
                out[-2:-2]=traversal_checks('differential','Differential',row)
    parser_count=count
    lexer_sources=['','foo 12','中文😀 abc','a\r\nb\tc','""','"a\\\"b"','"line\n😀"','/*a*/foo/*b*/','/*a/*b*/c*/','//x\r\nfoo','?foo!','\x00a','"unfinished','foo "unfinished','"\\','"\\\n','"foo" "bar"','/','/*','/* x','/*x*','"a"?"b"']
    rng=random.Random(20261124)
    units=['abc','12',' ','\t','\r\n','😀','中文','/*x*/','//x\n','"ok"','"a\\\"b"','?','"','\\']
    lexer_sources += [''.join(rng.choices(units,k=rng.randrange(1,7))) for _ in range(64)]
    lexer_sources=list(dict.fromkeys(lexer_sources))
    # UpstreamLexerOracle accepts one input per process, retaining an independent
    # recognizer/DFA for every case just like the native cursor below.
    for index,source in enumerate(lexer_sources):
        row=json.loads(subprocess.check_output([java,'-Dfile.encoding=UTF-8','-cp',str(directory)+os.pathsep+str(jar),'UpstreamLexerOracle','UnicodeModesLexer'],input=base64.b64encode(source.encode()).decode()+'\n',encoding='utf8'))
        token_values=', '.join('('+', '.join(q(value) for value in token)+')' for token in row['tokens'])
        positions=', '.join('('+str(line)+', '+str(col)+')' for line,col in row['errors'])
        out += ['///|',f'test "differential Lexer {index:03d}" {{',f'  let lexed = @runtime.deserialize(@unicode_modes_lexer.lexer_data()).tokenize_recovering({q(source)})',f'  @debug.assert_eq(lexed.tokens.map(t => (t.kind,t.text,t.start,t.end,t.line,t.column,t.channel)), [{token_values}])',f'  @debug.assert_eq(lexed.errors.map(error => match error {{ @runtime.LexicalError(line,col,_) => (line,col); _ => (-1,-1) }}), [{positions}])','}','']
        count+=1
    semantic_cases={'entry':['foo','12','foo foo',''], 'combined':['foo','12','foo foo',''], 'local':['a foo','a bar','b foo','b bar','a','a 12','a foo foo'], 'parameterized':['foo 12','12 foo','foo foo','12 12','foo','']}
    semantic_rules=read_interp(directory/'SemanticDifferential.interp')[1]
    for rule,sources in semantic_cases.items():
        payload=''.join(base64.b64encode(source.encode()).decode()+'\n' for source in sources)
        for enabled in [False,True]:
            for mode in ['SLL','LL','LL_EXACT_AMBIG_DETECTION']:
                result=subprocess.run([java,'-Dfile.encoding=UTF-8','-Dmoonantlr.semanticFlag='+str(enabled).lower(),'-Dmoonantlr.predictionMode='+mode,'-cp',str(directory)+os.pathsep+str(jar),'Oracle','SemanticDifferential',rule,'default'],input=payload,encoding='utf8',capture_output=True,check=True)
                rows=[json.loads(line) for line in result.stdout.splitlines()]
                if len(rows)!=len(sources):raise ValueError('Semantic reference case count differs')
                for index,(source,row) in enumerate(zip(sources,rows)):
                    count+=1
                    out += ['///|',f'test "differential semantic {rule} {enabled} {mode} {index:03d}" {{','  let trace = StringBuilder()',f'  let parsed = @semantic_differential.grammar().parse_default({q(source)}, start_rule={semantic_rules.index(rule)}, prediction_mode=@runtime.{mode}, semantics=semantic_differential_bindings({str(enabled).lower()}, trace))',f'  assert_eq(parsed.tree.to_sexpr(), {q(row["tree"])})',f'  assert_eq(parsed.context.get_text(), {q(row["contextText"])})',f'  @debug.assert_eq(parsed.diagnostics.map(d => (d.line.unwrap(), d.column.unwrap())), [{", ".join("("+str(line)+", "+str(col)+")" for line,col in row["parserErrors"])}])',f'  assert_eq(parsed.next_token.kind, {row["nextKind"]})',f'  assert_eq(parsed.next_token.text, {q(row["nextText"])})',f'  let expected : Json = @reference_json.parse({q(json.dumps(row["predictionEvents"],ensure_ascii=False,separators=(",",":")))})','  @debug.assert_eq(Json::array(parsed.prediction_events.map(event => event.to_json())), expected)',f'  assert_eq(trace.to_string(), {q(row["stdout"])})','}','']
                    out[-2:-2]=traversal_checks('semantic_differential','SemanticDifferential',row)
    semantic_count=count-parser_count-len(lexer_sources)
    labelled_sources=['x=1+2*3;','x=(1+2)^3','x=1+;y=2;','x=;','',';','x=(1+2','x=1^2^3; y=4/2;']
    payload=''.join(base64.b64encode(source.encode()).decode()+'\n' for source in labelled_sources)
    result=subprocess.run([java,'-Dfile.encoding=UTF-8','-cp',str(directory)+os.pathsep+str(jar),'Oracle','Typed','document','default'],input=payload,encoding='utf8',capture_output=True,check=True)
    rows=[json.loads(line) for line in result.stdout.splitlines()]
    if len(rows)!=len(labelled_sources):raise ValueError('Labelled reference case count differs')
    for index,(source,row) in enumerate(zip(labelled_sources,rows)):
        count+=1
        if not row['dispatchEvents']:raise ValueError('Missing independent generated-listener dispatch events')
        out += ['///|',f'test "differential labelled dispatch {index:03d}" {{',f'  let parsed = @typed.grammar().parse_default({q(source)})',f'  assert_eq(parsed.tree.to_sexpr(), {q(row["tree"])})',f'  assert_eq(parsed.context.get_text(), {q(row["contextText"])})',f'  @debug.assert_eq(typed_java_dispatch(parsed.context), {q(row["dispatchEvents"])})']
        out += traversal_checks('typed','Typed',row)+['}','']
    (ROOT/'tests/differential_oracle_test.mbt').write_text('\n'.join(out),encoding='utf8',newline='\n')
    manifest={'antlr':'4.13.2','antlr_sha256':ANTLR_SHA256,'cases':count,'parser_cases':parser_count,'lexer_cases':len(lexer_sources),'semantic_cases':semantic_count,'labelled_dispatch_cases':len(labelled_sources),'seeds':{'parser':20261123,'lexer':20261124},'rules':list(corpus()),'modes':['SLL','LL','LL_EXACT_AMBIG_DETECTION'],'grammar_sha256':{name:hashlib.sha256((ROOT/'grammars'/name).read_text(encoding='utf8').encode('utf8')).hexdigest() for name in ['Differential.g4','UnicodeModesLexer.g4','SemanticDifferential.g4','Typed.g4']}}
    (ROOT/'tests/differential-manifest.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf8',newline='\n')
    print('Independent differential comparisons:',count)

def main():
    cli=argparse.ArgumentParser(description=__doc__)
    cli.add_argument('--jar',type=Path,required=True)
    args=cli.parse_args();jar=args.jar.resolve()
    if hashlib.sha256(jar.read_bytes()).hexdigest()!=ANTLR_SHA256:cli.error('ANTLR jar checksum mismatch')
    scratch=ROOT/'.local';scratch.mkdir(exist_ok=True)
    # Fresh class directories prevent stale generated lexers or token vocabularies
    # from being mistaken for the current independent reference.
    with tempfile.TemporaryDirectory(prefix='differential-',dir=scratch) as directory:
        generate(jar,os.environ.get('JAVA','java'),os.environ.get('JAVAC','javac'),Path(directory))
if __name__=='__main__':main()
